cd /workspace; grep -E "^diff --git" pr/head.diff | sed 's/diff --git a\///; s/ b\/.*//' ; echo; echo ---STAT; git -C /workspace diff --stat 2>/dev/null | tail -1; python3 -I - <<'EOF'
import re
cur=None; add={}; rem={}
for line in open('pr/head.diff', errors='replace'):
    if line.startswith('diff --git'):
        cur=line.split(' b/')[-1].strip(); add[cur]=0; rem[cur]=0
    elif cur and line.startswith('+') and not line.startswith('+++'): add[cur]+=1
    elif cur and line.startswith('-') and not line.startswith('---'): rem[cur]+=1
for k in sorted(add, key=lambda k:-(add[k]+rem[k])):
    print(f"{add[k]:5d} {rem[k]:5d} {k}")
EOF

